lab.solution:
def display_name(value):
    clean = value.strip()
    if not clean:
        raise ValueError('display name is required')
    return clean

assert display_name(' Ana ') == 'Ana'
try:
    display_name('   ')
except ValueError:
    pass
else:
    raise AssertionError('empty display name should fail')

